import React from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { mockVideos } from '../data/mockData';
import { FaArrowLeft, FaClipboardCheck } from 'react-icons/fa';
import '../styles/Videoplayer.css';

const Videoplayer = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const video = mockVideos.find(v => v.id === parseInt(id));

  if (!video) {
    return <div className="player-container"><h2>Video not found</h2></div>;
  }

  const handleVideoEnd = () => {
    // In a real app with YouTube API, we'd detect end automatically.
    // For iframe, we instruct the user to click the button.
    navigate(`/quiz/${id}`);
  };

  return (
    <div className="player-container">
      <div className="player-header">
        <button onClick={() => navigate('/student')} className="back-btn">
          <FaArrowLeft style={{ marginRight: '10px' }} /> Back to Dashboard
        </button>
        <h1 className="player-title">{video.title}</h1>
      </div>

      <div className="video-wrapper">
        <iframe
          src={video.url}
          title={video.title}
          className="video-iframe"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
          allowFullScreen
        ></iframe>
      </div>

      <div className="player-actions">
        <div className="player-info">
          <h2>{video.title}</h2>
          <p>{video.description}</p>
        </div>

        <div className="next-step">
          <p>Finished watching?</p>
          <button onClick={handleVideoEnd} className="quiz-btn">
            <FaClipboardCheck style={{ marginRight: '10px' }} />
            Take Quiz to Unlock Next Module
          </button>
        </div>
      </div>
    </div>
  );
};

export default Videoplayer;
